<?php
require_once __DIR__.'/../config/app.php';require_admin();
if(is_post()){verify_csrf();$productId=(int)($_POST['product_id']??0);$type=$_POST['type']??'';$quantity=max(1,(int)($_POST['quantity']??0));$notes=trim($_POST['notes']??'');if(!in_array($type,['addition','correction'],true)){flash('danger','Jenis mutasi tidak valid.');redirect('admin/stock.php');}$pdo=db();$pdo->beginTransaction();try{$stmt=$pdo->prepare('SELECT stock,name FROM products WHERE id=? FOR UPDATE');$stmt->execute([$productId]);$product=$stmt->fetch();if(!$product)throw new RuntimeException('Produk tidak ditemukan.');$before=(int)$product['stock'];$after=$type==='addition'?$before+$quantity:$before-$quantity;if($after<0)throw new RuntimeException('Stok tidak boleh negatif.');$delta=$type==='addition'?$quantity:-$quantity;$pdo->prepare('UPDATE products SET stock=? WHERE id=?')->execute([$after,$productId]);$pdo->prepare('INSERT INTO stock_movements(product_id,user_id,movement_type,quantity,stock_before,stock_after,notes) VALUES(?,?,?,?,?,?,?)')->execute([$productId,current_user()['id'],$type,$delta,$before,$after,$notes?:'Penyesuaian stok manual']);$pdo->commit();flash('success','Stok '.$product['name'].' berhasil diperbarui.');}catch(Throwable $e){$pdo->rollBack();flash('danger',$e->getMessage());}redirect('admin/stock.php');}
$products=db()->query('SELECT * FROM products ORDER BY stock ASC,name')->fetchAll();$movements=db()->query('SELECT sm.*,p.name product_name,u.name admin_name FROM stock_movements sm JOIN products p ON p.id=sm.product_id LEFT JOIN users u ON u.id=sm.user_id ORDER BY sm.created_at DESC LIMIT 50')->fetchAll();$pageTitle='Manajemen Stok';require APP_ROOT.'/includes/admin-header.php';
?>
<div class="row g-4 mb-4"><div class="col-lg-5"><div class="admin-card"><div class="admin-card-header"><strong>Penyesuaian stok</strong></div><div class="admin-card-body"><form method="post"><?= csrf_field() ?><div class="mb-3"><label class="form-label">Produk</label><select class="form-select" name="product_id" required><option value="">Pilih produk</option><?php foreach($products as $product):?><option value="<?= $product['id'] ?>"><?= e($product['name']) ?> (stok <?= $product['stock'] ?>)</option><?php endforeach;?></select></div><div class="row g-3 mb-3"><div class="col-6"><label class="form-label">Tindakan</label><select class="form-select" name="type"><option value="addition">Tambah stok</option><option value="correction">Kurangi/koreksi</option></select></div><div class="col-6"><label class="form-label">Jumlah</label><input class="form-control" type="number" name="quantity" min="1" required></div></div><div class="mb-3"><label class="form-label">Alasan</label><textarea class="form-control" name="notes" required></textarea></div><button class="btn btn-primary">Simpan Mutasi</button></form></div></div></div><div class="col-lg-7"><div class="admin-card"><div class="admin-card-header"><strong>Kondisi stok</strong></div><div class="table-responsive" style="max-height:430px"><table class="table mb-0"><thead><tr><th>Produk</th><th>Stok</th><th>Batas</th><th>Kondisi</th></tr></thead><tbody><?php foreach($products as $product):?><tr><td><strong><?= e($product['name']) ?></strong><div class="small text-muted"><?= e($product['sku']) ?></div></td><td><?= $product['stock'] ?></td><td><?= $product['minimum_stock'] ?></td><td><span class="badge text-bg-<?= $product['stock']==0?'danger':($product['stock']<=$product['minimum_stock']?'warning':'success') ?>"><?= $product['stock']==0?'Habis':($product['stock']<=$product['minimum_stock']?'Menipis':'Aman') ?></span></td></tr><?php endforeach;?></tbody></table></div></div></div></div><div class="admin-card"><div class="admin-card-header"><strong>Riwayat mutasi terakhir</strong></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Waktu</th><th>Produk</th><th>Jenis</th><th>Perubahan</th><th>Stok</th><th>Admin/Catatan</th></tr></thead><tbody><?php foreach($movements as $row):?><tr><td class="small"><?= date('d/m/Y H:i',strtotime($row['created_at'])) ?></td><td><?= e($row['product_name']) ?></td><td><?= e(ucfirst($row['movement_type'])) ?></td><td class="fw-bold <?= $row['quantity']>=0?'text-success':'text-danger' ?>"><?= $row['quantity']>0?'+':'' ?><?= $row['quantity'] ?></td><td><?= $row['stock_before'] ?> → <?= $row['stock_after'] ?></td><td><div class="small"><?= e($row['admin_name']??'Sistem') ?></div><div class="small text-muted"><?= e($row['notes']) ?></div></td></tr><?php endforeach;?></tbody></table></div></div>
<?php require APP_ROOT.'/includes/admin-footer.php';?>
